import {HEROES, ATTACKS, DEFENSES, RULES, createGame, legalTargets, availableAttacks, availableDefenses, previewAttack, previewDefense, playerAttack, resolveAiDefense, chooseAiAttack, playerDefend} from './engine.js';
import {icon, portrait, castleArt, landscape} from './art.js';
const $=id=>document.getElementById(id),ids=['kora','ilda','neris'];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const typeNames={stone:'Taş',arrow:'Ok',sound:'Ses',rally:'Temel'},typeIcons={stone:'stone',arrow:'arrow',sound:'sound',rally:'flag'};
const castleNames={left:'Sol kule',main:'Ana kale',right:'Sağ kule'},modeNames={quick:'Hızlı',heavy:'Ağır',disrupt:'Boz',prepare:'Hazırlan',basic:'Temel atış'};
const STORE='kale-muhafizlari-v2';
let settings={sound:false,trainingEnabled:true,bestTraining:0};
let state,selectedHero=null,selectedMode=null,selectedTarget=null,selectedDefense='brace',busy=false,generation=0,modalGeneration=0,trainingFrame=0,trainingSession=null,finishShown=false,audioContext,centerResult=null;
const timers=new Set(),reducedMotion=matchMedia('(prefers-reduced-motion: reduce)');let storageAvailable=true;
function readStore(key){try{return JSON.parse(localStorage.getItem(key)||'null');}catch{return null;}}
const saved=readStore(STORE),oldSaved=readStore('kale-muhafizlari-v1');
const oldSettings=saved?.settings||oldSaved?.settings;
if(oldSettings)settings={sound:oldSettings.sound===true,trainingEnabled:oldSettings.trainingEnabled!==false,bestTraining:Math.max(0,Math.min(3,Math.trunc(Number(oldSettings.bestTraining)||0)))};
function validState(s){try{if(s?.version!==2||!['playerAttack','playerDefense','aiAttack','aiDefense','finished'].includes(s.phase)||!Number.isInteger(s.round)||s.round<1||s.round>10000||!Number.isInteger(s.rng)||![0,1].includes(s.turnInRound)||!['player','enemy'].includes(s.firstSide))return false;for(const side of ['player','enemy']){if(!Number.isInteger(s.energy?.[side])||s.energy[side]<0||s.energy[side]>6||!Number.isInteger(s.decisionIndex?.[side])||!Number.isInteger(s.attackCount?.[side])||s.decisionIndex[side]<0||s.attackCount[side]<0||!Number.isInteger(s.trainingBySide?.[side])||s.trainingBySide[side]<0||s.trainingBySide[side]>3)return false;if(!Array.isArray(s.castles?.[side])||s.castles[side].length!==3)return false;for(const id of ['left','main','right']){const c=s.castles[side].find(c=>c.id===id);if(!c||c.maxHp!==(id==='main'?420:240)||!Number.isFinite(c.hp)||c.hp<0||c.hp>c.maxHp)return false;}for(const id of ids){const h=s.heroes?.[side]?.[id];if(!h||!['left','main','right'].includes(h.castleId)||![0,18].includes(h.charge)||!['readyAt','retreatRounds','retreatUntilRound'].every(k=>Number.isInteger(h[k])&&h[k]>=0))return false;}}if(!s.training||typeof s.training.enabled!=='boolean'||!Number.isInteger(s.training.power)||s.training.power<0||s.training.power>3||!Array.isArray(s.log)||s.log.some(x=>typeof x!=='string'))return false;if(['playerDefense','aiDefense'].includes(s.phase)){const p=s.pendingAttack;if(!p||!ATTACKS[p.attackId]||!['left','main','right'].includes(p.targetId)||!HEROES[p.heroId]||!Number.isFinite(p.damage)||p.damage<0||p.damage>200)return false;}if(s.phase==='finished'&&!['player','enemy'].includes(s.winner))return false;return true;}catch{return false;}}
function freshGame(){return createGame({seed:`duel-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,firstSide:state?.firstSide?(state.firstSide==='player'?'enemy':'player'):'random',training:{power:settings.bestTraining},trainingEnabled:settings.trainingEnabled});}
state=validState(saved?.state)?saved.state:freshGame();
function persist(){try{localStorage.setItem(STORE,JSON.stringify({settings,state}));}catch{storageAvailable=false;}}
function schedule(fn,delay){const token=generation;const id=setTimeout(()=>{timers.delete(id);if(token!==generation)return;if($('modal').open){schedule(fn,150);return;}fn();},delay);timers.add(id);}
function cancelTimers(){generation++;for(const id of timers)clearTimeout(id);timers.clear();$('effects').innerHTML='';centerResult=null;}
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('show'),3000);}
function announce(message){$('live-status').textContent=message;}
function sound(kind){if(!settings.sound)return;try{audioContext??=new(window.AudioContext||window.webkitAudioContext)();if(audioContext.state==='suspended')audioContext.resume();const t=audioContext.currentTime,tones=kind==='win'?[392,494,587,784]:kind==='guard'?[294,440]:kind==='heavy'?[85,65,45]:kind==='hit'?[110,75]:[220];tones.forEach((f,i)=>{const o=audioContext.createOscillator(),g=audioContext.createGain();o.type=['heavy','hit'].includes(kind)?'triangle':'sine';o.frequency.setValueAtTime(f,t+i*.08);g.gain.setValueAtTime(0,t+i*.08);g.gain.linearRampToValueAtTime(.06,t+i*.08+.01);g.gain.exponentialRampToValueAtTime(.001,t+i*.08+.25);o.connect(g);g.connect(audioContext.destination);o.start(t+i*.08);o.stop(t+i*.08+.27);});}catch{}}
function soundIcon(){$('sound-button').innerHTML=icon(settings.sound?'volume':'mute');$('sound-button').setAttribute('aria-label',settings.sound?'Sesi kapat':'Sesi aç');$('sound-button').setAttribute('aria-pressed',String(settings.sound));}
$('landscape').innerHTML=landscape;$('help-button').innerHTML=icon('help');$('settings-button').innerHTML=icon('settings');$('close-modal').innerHTML=icon('close');soundIcon();
function isReady(side,id){const h=state.heroes[side][id];return !h.retreatRounds&&h.readyAt<=state.decisionIndex[side];}
function actionId(){return selectedMode==='basic'?'rally':selectedHero&&selectedMode?`${selectedHero}:${selectedMode}`:null;}
function energyHTML(side){return `<span class="resource-label">⚡</span><span class="energy-pips">${Array.from({length:6},(_,i)=>`<span class="energy-pip ${i<state.energy[side]?'filled':''}"></span>`).join('')}</span><span>${state.energy[side]}/6</span><small>+3 saldırı başında</small>`;}
function stationHeroes(side,castleId){return ids.filter(id=>state.heroes[side][id].castleId===castleId).sort((a,b)=>(HEROES[a].castleId===castleId?-1:1)-(HEROES[b].castleId===castleId?-1:1));}
function renderCastles(side){const phase=state.phase,playerChoice=side==='player'&&!busy&&['playerAttack','playerDefense'].includes(phase),targetChoice=side==='enemy'&&!busy&&phase==='playerAttack'&&selectedMode&&selectedMode!=='prepare';const legal=legalTargets(state,side==='enemy'?'player':'enemy').map(c=>c.id);return state.castles[side].map(c=>{const stationed=stationHeroes(side,c.id);const chosen=side==='player'&&selectedHero&&state.heroes.player[selectedHero].castleId===c.id;const targeted=side==='enemy'&&selectedTarget===c.id&&phase==='playerAttack';const incoming=side==='player'&&phase==='playerDefense'&&state.pendingAttack.targetId===c.id;const locked=c.id==='main'&&!legal.includes('main')&&c.hp>0&&phase!=='finished';const prepared=stationed.some(id=>state.heroes[side][id].charge);const selectedStation=stationed.includes(selectedHero)?selectedHero:stationed[0];const hero=selectedStation?state.heroes[side][selectedStation]:null;let marker=locked?`${icon('lock')} Yan kuleyi aş`:prepared?'✦ HAZIR +18':'';let markerClass=prepared?'charged':'';if(chosen&&phase==='playerAttack'){marker=selectedHero?`${HEROES[selectedHero].name} seçili`:'';markerClass='gold';}if(targeted){marker='HEDEFİN';markerClass='red';}if(incoming){marker='SALDIRI BURAYA';markerClass='red';}if(!marker&&side==='player'&&hero&&!isReady(side,selectedStation)){marker=hero.retreatRounds?'GERİ ÇEKİLİYOR':'DİNLENİYOR';markerClass='rest';}
return `<button class="castle-button ${c.id==='main'?'main':''} ${c.hp<=0?'fallen':''} ${playerChoice&&c.hp>0?'selectable':''} ${chosen?'selected':''} ${targetChoice&&!locked&&c.hp>0?'targetable':''} ${targeted?'targeted':''} ${incoming?'incoming':''}" data-castle="${c.id}" data-side="${side}" ${c.hp<=0||(!playerChoice&&!targetChoice)?'disabled':''} aria-label="${side==='enemy'?'Rakip':'Senin'} ${castleNames[c.id]}, ${c.hp}/${c.maxHp} can. ${stationed.map(id=>HEROES[id].name).join(', ')}${locked?'. Ana kale kilitli.':''}" title="${locked?'Bir yan kule yıkılmalı':stationed.map(id=>HEROES[id].name).join(' / ')}">${marker?`<span class="castle-state ${markerClass}">${marker}</span>`:''}${castleArt(side,c.id==='main',c.hp<=0)}${c.hp>0?stationed.map((id,i)=>`<span class="hero-station ${i?'extra':''} ${state.heroes[side][id].charge?'charged':''} ${!isReady(side,id)?'exhausted':''} ${state.heroes[side][id].retreatRounds?'retreat':''}">${portrait(id)}</span>`).join(''):''}<span class="castle-label">${c.hp<=0?'Yıkıldı':castleNames[c.id]}</span><span class="castle-hp"><span class="hp-track ${c.hp/c.maxHp<.3?'low':''}"><span class="hp-fill" style="width:${c.hp/c.maxHp*100}%"></span></span><span class="hp-number">${c.hp}/${c.maxHp}</span></span></button>`;}).join('');}
function actorHeading(hero,title,subtitle){return `${hero?`<span class="actor-portrait">${portrait(hero)}</span>`:''}<span><strong>${title}</strong><small>${subtitle}</small></span>`;}
function setCenter(){const p=state.pendingAttack;const center=$('battle-center');center.className='battle-center';if(centerResult){center.classList.add('result');center.innerHTML=`<strong>${esc(centerResult.title)}</strong><small>${esc(centerResult.detail)}</small>`;return;}if(state.phase==='playerDefense'){center.classList.add('incoming');center.innerHTML=`<strong>${icon(typeIcons[p.type])}${HEROES[p.heroId].name} · ${modeNames[p.mode]}</strong><small>${typeNames[p.type]} → ${castleNames[p.targetId]} · <b>${p.damage} ham hasar</b> · ${p.cost}⚡</small>`;}else if(state.phase==='aiDefense'){center.innerHTML=`<strong>${HEROES[p.heroId].name} saldırıyor</strong><small>${typeNames[p.type]} → ${castleNames[p.targetId]} · ${p.damage} ham hasar</small>`;}else if(state.phase==='aiAttack'){center.innerHTML=`<strong>Rakip hamlesini kuruyor</strong><small>${state.round===1?'İlk hamle rakipte · Başlayan 3⚡, yanıtlayan 4⚡':'Enerji, hazırlık ve açıklarını değerlendiriyor.'}</small>`;}else if(state.phase==='finished'){center.innerHTML=`<strong>${state.winner==='player'?'Zafer senin!':'Ana kalen düştü.'}</strong><small>${state.round} tur · Yeniden denemeye hazır mısın?</small>`;}else{const text=!selectedHero?'Kendi kalene dokun':!selectedMode?'Bir hamle seç':selectedMode==='prepare'?'Bir sonraki hamleni hazırla':!selectedTarget?'Rakip kaleye nişan al':'Hamlen hazır';center.innerHTML=`<strong>${text}</strong><small>${selectedMode==='prepare'?'Bu tur vurmazsın. Enerji ve hazırlık kazanırsın.':selectedTarget?`${HEROES[selectedHero].name} → ${castleNames[selectedTarget]}`:state.round===1?`İlk hamle ${state.firstSide==='player'?'sende':'rakipte'} · Başlayan 3⚡, yanıtlayan 4⚡`:'Saldırı ve savunma aynı enerjiyi paylaşır.'}</small>`;}}
function attackPanel(){const actions=availableAttacks(state,'player');const basic=actions.find(a=>a.id==='rally');$('round-number').innerHTML=`<button class="basic-shortcut ${selectedMode==='basic'?'selected':''}" data-basic ${busy?'disabled':''} aria-label="Ücretsiz temel atış, 18 hasar">0⚡ Temel 18</button>`;if(!selectedHero){$('command-actor').innerHTML=actorHeading(null,'Hamleni sahada kur',`${state.round}. tur · Önce kendi kaleni seç`);$('command-content').innerHTML=`<div class="choose-source">${icon('flag')}<h2>Bir kaleden başla.</h2><p>Muhafızını sahada seç. Sonra hamleni ve rakip hedefini belirle.</p><div class="step-row"><span>1 Kahraman</span> › 2 Hamle › 3 Hedef</div></div>`;$('move-preview').innerHTML='<div class="preview-row"><span>Enerjin</span><strong class="gold">'+state.energy.player+'/6</strong></div><p class="preview-note">Ağır vuruş mu, savunmaya ayıracağın enerji mi?</p>';$('action-button').textContent='Önce kendi kaleni seç';$('action-button').disabled=true;$('action-note').textContent='Kahramanın saldırırsa hemen sonraki savunmada dinlenir.';return;}
const h=state.heroes.player[selectedHero];$('command-actor').innerHTML=actorHeading(selectedHero,HEROES[selectedHero].name,`${state.round}. tur · ${typeNames[HEROES[selectedHero].type]}${h.charge?' · ✦ Hazır +18':''}${!isReady('player',selectedHero)?' · Dinleniyor':''}`);
$('command-content').innerHTML=`<div class="attack-grid">${['quick','heavy','disrupt','prepare'].map(mode=>{const a=actions.find(a=>a.id===`${selectedHero}:${mode}`);const details={quick:'Az enerji, hızlı baskı',heavy:'Büyük hasar, az rezerv',disrupt:'İsabet: hazırlığı boz',prepare:'+2⚡ ve +18 hazırlık'};return `<button class="attack-choice ${selectedMode===mode?'selected':''}" data-mode="${mode}" ${!a.available||busy?'disabled':''} aria-pressed="${selectedMode===mode}" aria-label="${modeNames[mode]}, ${a.cost} enerji, ${mode==='prepare'?'+2 enerji ve tek kullanımlık +18 hazırlık':a.damage+' ham hasar'}. ${a.reason||''}"><span class="cost-badge">${a.cost}⚡</span><strong>${icon(mode==='prepare'?'star':mode==='disrupt'?'sound':typeIcons[a.type])}${modeNames[mode]}</strong><span class="mode-value">${mode==='prepare'?'Bu tur saldırma':a.damage+' hasar'}</span><small>${details[mode]}</small></button>`;}).join('')}</div>`;
const id=actionId(),a=id?actions.find(a=>a.id===id):null;const preview=a?previewAttack(state,{attackId:id,targetId:selectedTarget}):null;let html='';if(!a){html='<div class="preview-row"><span>Bir hamle seç</span><strong class="gold">'+state.energy.player+'⚡ hazır</strong></div><p class="preview-note">Kalene yeniden dokunarak aynı kaledeki diğer muhafıza geçebilirsin.</p>';}else if(a.mode==='prepare'){html=`<div class="preview-row"><span>Enerji <strong>${state.energy.player} → ${a.energyAfter}</strong></span><strong class="gold">Hazırlık: +18</strong></div><p class="preview-note">Saldırından vazgeç. Gücü sonraki vuruşta ya da eşleşen siperde kullan.</p>`;}else{const possible=preview.possibleBlocks.filter(p=>p.available),best=possible.length?Math.min(...possible.map(p=>p.damage)):Math.max(0,a.damage-12),brace=Math.max(0,a.damage-12);html=`<div class="preview-row"><span>${selectedTarget?castleNames[selectedTarget]:'Rakip hedefini seç'}</span><strong class="gold">${a.baseDamage}${a.chargeBonus?' + '+a.chargeBonus:''}${a.trainingBonus?' + '+a.trainingBonus:''} = ${a.damage}</strong></div><div class="preview-row"><span>${selectedTarget?`Net hasar: ${best}–${brace}`:'Hedefe göre savunma hesabı'}</span><strong class="${a.energyAfter<2?'warning':'good'}">${state.energy.player} → ${a.energyAfter}⚡</strong></div>`;}
$('move-preview').innerHTML=html;$('action-button').disabled=busy||!a?.available||!(a.mode==='prepare'||selectedTarget&&legalTargets(state,'player').some(t=>t.id===selectedTarget));$('action-button').innerHTML=a?.mode==='prepare'?`${icon('star')} Hazırlan, bu saldırıdan vazgeç`:!selectedMode?'Bir hamle seç':!selectedTarget?'Şimdi rakip kaleyi seç':`${icon(typeIcons[a.type])} ${modeNames[a.mode]} · ${castleNames[selectedTarget]}`;
$('action-note').textContent=a?.mode==='disrupt'?'Hasar geçerse: hedefin hazırlığı silinir, rakip −1⚡.':a?.mode==='prepare'?'Hazırlık birikmez. Rakibin bozucu darbesiyle silinebilir.':a?.mode==='basic'?'Ücretsiz zayıf atış. Kahramanı yormaz; hazırlığı tüketmez.':a?.energyAfter<2?`${HEROES[selectedHero].name} dinlenir. 2⚡ kalmadığı için özel siper kullanamazsın.`:`${HEROES[selectedHero].name} saldırırsa hemen sonraki savunmada dinlenir.`;
}
function defensePanel(){const p=state.pendingAttack,choices=availableDefenses(state,'player');if(!choices.find(d=>d.id===selectedDefense&&d.available))selectedDefense='brace';$('command-actor').innerHTML=actorHeading(null,'Savunmayı sen kur',`${state.round}. tur · ${castleNames[p.targetId]} hedefte`);$('round-number').textContent=`${state.energy.player}⚡ rezerv`;
$('command-content').innerHTML=`<div class="defense-grid">${choices.map(d=>{const pv=previewDefense(state,d.id),matched=d.id!=='brace'&&pv.effective,why=d.id==='brace'?'Enerjini sakla':!d.available?(state.heroes.player[d.heroId].retreatRounds?'Çekiliyor':!isReady('player',d.heroId)?'Dinleniyor':'Enerji yetmez'):!matched?'Yanlış tür · 0':d.localBonus?'Yerel siper +8':'Her kaleyi korur';return `<button class="defense-choice ${d.id==='brace'?'brace':''} ${matched?'match':'wrong'} ${selectedDefense===d.id?'selected':''}" data-defense="${d.id}" ${!d.available||busy?'disabled':''} aria-pressed="${selectedDefense===d.id}" aria-label="${d.heroId?HEROES[d.heroId].name:'Evrensel siper'}, ${pv.blocked} engeller, ${d.cost} enerji. ${d.reason||why}">${d.heroId?portrait(d.heroId):icon('shield')}<span class="defense-info"><strong>${d.heroId?HEROES[d.heroId].name:'Siper'} · ${d.cost}⚡</strong><small>${why}</small></span><span class="defense-value">${pv.blocked}<small>engeller</small></span></button>`;}).join('')}</div>`;
const pv=previewDefense(state,selectedDefense),target=state.castles.player.find(c=>c.id===p.targetId);$('move-preview').innerHTML=`<div class="preview-row"><span><strong>${p.damage} − ${pv.blocked} = ${pv.damage}</strong> hasar</span><strong class="${pv.energyAfter<2?'warning':'good'}">Siper: ${state.energy.player} → ${pv.energyAfter}⚡</strong></div><div class="preview-row"><span>${castleNames[p.targetId]} canı</span><strong class="${target.hp<=pv.damage?'warning':''}">${target.hp} → ${Math.max(0,target.hp-pv.damage)}</strong></div>`;$('action-button').disabled=busy;$('action-button').innerHTML=`${icon('shield')} ${selectedDefense==='brace'?'Siper al · enerjini sakla':HEROES[selectedDefense].name+' ile koru'}`;$('action-note').textContent=selectedDefense==='brace'?(state.attackCount.player===0?'Ücretsiz 12 koruma. İlk saldırı başlangıcında enerji yenilenmez.':'Ücretsiz 12 koruma. Sonraki saldırı başında +3⚡ (en çok 6).'):!pv.effective?'Yanlış tür: 0 koruma, 2 enerji gider ve kahraman yorulur.':`${HEROES[selectedDefense].name} sonraki saldırıda dinlenir. ${state.attackCount.player===0?'İlk saldırıda yenilenme yok.':'+3⚡ tur başında.'}${pv.energyDrained?' Bozma: −1⚡.':''}`;
}
function busyPanel(){$('round-number').textContent=`TUR ${state.round}`;$('command-actor').innerHTML=actorHeading(state.pendingAttack?.heroId||null,centerResult?'Hamle sonuçlandı':'Meydan hareketleniyor',centerResult?.detail||'Saldırı ve savunma sırayla çözülür');$('command-content').innerHTML=`<div class="choose-source">${icon(state.phase==='aiDefense'?'shield':'stone')}<h2>${centerResult?.title||(state.phase==='aiDefense'?'Rakip savunmasını seçiyor.':'Bir sonraki hamle geliyor.')}</h2><p>${centerResult?'Sonuçları savaş alanında izle.':'Kale canları, enerji ve kahramanların hazırlığı sahada açık.'}</p></div>`;$('move-preview').innerHTML=`<div class="preview-row"><span>Senin enerjin</span><strong>${state.energy.player}/6</strong></div><div class="preview-row"><span>Rakibin enerjisi</span><strong>${state.energy.enemy}/6</strong></div>`;$('action-button').disabled=true;$('action-button').textContent='Hamle sürüyor…';$('action-note').textContent='Acele gerekmiyor. Kararların için süre sınırı yok.';}
function render(){if(state.phase==='playerAttack'&&selectedTarget&&!legalTargets(state,'player').some(c=>c.id===selectedTarget))selectedTarget=null;$('enemy-resource').innerHTML=energyHTML('enemy');$('player-resource').innerHTML=energyHTML('player');$('enemy-resource').setAttribute('aria-label',`Rakip enerji ${state.energy.enemy}/6`);$('player-resource').setAttribute('aria-label',`Enerjin ${state.energy.player}/6`);$('enemy-castles').innerHTML=renderCastles('enemy');$('player-castles').innerHTML=renderCastles('player');setCenter();$('training-indicator').textContent=state.training.enabled&&state.training.power?`✦ Kora +${state.training.power}`:'';document.querySelector('.command-panel').classList.toggle('defense-mode',state.phase==='playerDefense');$('arena-caption').textContent=state.phase==='playerDefense'?'Yerel muhafız +8 korur. Her hazır muhafız başka kaleyi de koruyabilir.':'Bir yan kuleyi yık. Ana kaleye yolu aç.';
if(state.phase==='finished'){ $('command-actor').innerHTML=actorHeading(null,state.winner==='player'?'Zafer senin!':'Yeniden ayağa kalk',`${state.round} tur · Düello tamamlandı`);$('round-number').textContent='SONUÇ';$('command-content').innerHTML=`<div class="choose-source">${icon(state.winner==='player'?'flag':'shield')}<h2>${state.winner==='player'?'Krallık güvende.':'Yeni bir plan yap.'}</h2><p>Enerjini, hazırlığını ve muhafızlarını farklı bir sırayla kullan.</p></div>`;$('move-preview').innerHTML=`<div class="preview-row"><span>Ayakta kalan kalen</span><strong>${state.castles.player.filter(c=>c.hp>0).length}/3</strong></div>`;$('action-button').disabled=false;$('action-button').innerHTML=icon('refresh')+' Yeni düello';$('action-note').textContent=`Rövanşta ilk hamle ${state.firstSide==='player'?'rakipte':'sende'} olacak.`;}
else if(busy||['aiAttack','aiDefense'].includes(state.phase))busyPanel();else if(state.phase==='playerDefense')defensePanel();else attackPanel();persist();}
function point(side,id){const arena=$('arena').getBoundingClientRect(),node=document.querySelector(`[data-side="${side}"][data-castle="${id}"]`);if(!node)return{x:arena.width/2,y:arena.height/2};const r=node.getBoundingClientRect();return{x:r.left-arena.left+r.width/2,y:r.top-arena.top+r.height*.46};}
function showImpact(attack,event){const targetSide=attack.side==='player'?'enemy':'player',t=point(targetSide,attack.targetId);const label=document.createElement('span');label.className='hit-label';label.style.cssText=`--tx:${t.x}px;--ty:${t.y}px`;label.innerHTML=`<small>${event.blocked} engellendi</small>−${event.hpLost}`;$('effects').append(label);const ring=document.createElement('span');ring.className='impact-ring';ring.style.cssText=`--tx:${t.x}px;--ty:${t.y}px`;$('effects').append(ring);document.querySelector(`[data-side="${targetSide}"][data-castle="${attack.targetId}"]`)?.classList.add(event.castleFell?'falling':'hit');if(event.blocked){const shield=document.createElement('span');shield.className='shield-effect';shield.style.cssText=ring.style.cssText;shield.innerHTML=icon('shield');$('effects').append(shield);schedule(()=>shield.remove(),750);}sound(event.effective?'guard':attack.mode==='heavy'?'heavy':'hit');schedule(()=>{label.remove();ring.remove();},1450);}
function resolveAnimated(attack,next,done){busy=true;render();const s=point(attack.side,state.heroes[attack.side][attack.heroId].castleId),t=point(attack.side==='player'?'enemy':'player',attack.targetId);const projectile=document.createElement('span');projectile.className=`projectile ${attack.type} ${attack.mode}`;projectile.style.cssText=`--sx:${s.x}px;--sy:${s.y}px;--tx:${t.x}px;--ty:${t.y}px`;projectile.innerHTML=icon(typeIcons[attack.type]);$('effects').append(projectile);sound('select');schedule(()=>{projectile.remove();state=next;const e=state.lastEvent;centerResult={title:e.castleFell?`${castleNames[e.targetId]} yıkıldı!`:`${e.hpLost} hasar · ${e.blocked} engellendi`,detail:e.energyDrained?`Bozma etkisi: −${e.energyDrained} enerji${e.preparationCleared?.length?' ve hazırlık silindi':''}`:`${state.lastDefense?.name||'Savunma'} · ${state.lastDefense?.cost||0}⚡`};render();showImpact(attack,e);announce(centerResult.title+'. '+centerResult.detail);schedule(()=>{centerResult=null;done();},950);},reducedMotion.matches?30:520);}
function settlePreparation(next,side){state=next;busy=true;centerResult={title:`${HEROES[state.lastEvent.heroId].name} hazırlandı`,detail:`+${state.lastEvent.energyGained}⚡ · Sonraki vuruşa veya sipere +18`};render();announce(centerResult.title);sound('guard');schedule(()=>{centerResult=null;drive();},1000);}
function drive(){if(state.phase==='finished'){busy=false;render();if(!finishShown){finishShown=true;schedule(showFinish,700);if(state.winner==='player')sound('win');}return;}if(state.phase==='aiDefense'){busy=true;render();schedule(()=>{try{const attack=state.pendingAttack,next=resolveAiDefense(state);resolveAnimated(attack,next,drive);}catch(e){recover(e);}},500);}else if(state.phase==='aiAttack'){busy=true;render();schedule(()=>{try{const next=chooseAiAttack(state);if(next.lastEvent?.kind==='prepared'){settlePreparation(next,'enemy');return;}state=next;busy=false;selectedDefense='brace';render();announce(`${HEROES[state.pendingAttack.heroId].name}, ${castleNames[state.pendingAttack.targetId]} hedefine ${state.pendingAttack.damage} hasar hazırlıyor. Savunmanı seç.`);}catch(e){recover(e);}},650);}else{busy=false;selectedHero=null;selectedMode=null;selectedTarget=null;render();announce(`${state.round}. tur. Kendi kalene dokun ve hamleni kur.`);}}
function recover(e){console.error(e);cancelTimers();busy=false;toast('Hamle tamamlanamadı. Ayarlardan yeni düello başlatabilirsin.');render();}
function takeAction(){if(busy)return;if(state.phase==='finished'){newGame();return;}if(state.phase==='playerAttack'){const id=actionId();if(!id)return;try{const next=playerAttack(state,{attackId:id,targetId:selectedTarget});busy=true;if(next.lastEvent.kind==='prepared'){settlePreparation(next,'player');return;}state=next;drive();}catch(e){toast(e.message);}}else if(state.phase==='playerDefense'){try{const attack=state.pendingAttack,next=playerDefend(state,{defenseId:selectedDefense});resolveAnimated(attack,next,drive);}catch(e){toast(e.message);}}}
function newGame(){cancelTimers();closeModal();state=freshGame();selectedHero=null;selectedMode=null;selectedTarget=null;selectedDefense='brace';finishShown=false;busy=false;render();drive();}
$('arena').addEventListener('click',e=>{const b=e.target.closest('[data-castle]');if(!b||b.disabled||busy)return;const c=b.dataset.castle,side=b.dataset.side;if(side==='player'){const stationed=stationHeroes('player',c);if(!stationed.length)return;const current=stationed.indexOf(selectedHero);selectedHero=stationed[(current+1)%stationed.length];if(state.phase==='playerDefense'){selectedDefense=selectedHero;const d=availableDefenses(state,'player').find(d=>d.id===selectedDefense);if(!d.available){toast(d.reason);selectedDefense='brace';}}else{selectedMode=null;selectedTarget=null;}sound('select');render();}else if(state.phase==='playerAttack'&&selectedMode&&selectedMode!=='prepare'){if(!legalTargets(state,'player').some(t=>t.id===c)){toast('Ana kaleye ulaşmak için önce bir yan kuleyi yık.');return;}selectedTarget=c;sound('select');render();}});
$('command-content').addEventListener('click',e=>{const m=e.target.closest('[data-mode]'),d=e.target.closest('[data-defense]');if(busy)return;if(m&&!m.disabled){selectedMode=m.dataset.mode;selectedTarget=null;sound('select');render();}if(d&&!d.disabled){selectedDefense=d.dataset.defense;sound('select');render();}});
$('round-number').addEventListener('click',e=>{if(!e.target.closest('[data-basic]')||busy||state.phase!=='playerAttack')return;const basic=availableAttacks(state,'player').find(a=>a.id==='rally');selectedHero=basic.heroId;selectedMode='basic';selectedTarget=null;render();});
$('action-button').addEventListener('click',takeAction);$('sound-button').addEventListener('click',()=>{settings.sound=!settings.sound;soundIcon();persist();if(settings.sound)sound('select');});
function openModal(html){modalGeneration++;cancelAnimationFrame(trainingFrame);trainingSession=null;$('modal-content').innerHTML=html;const heading=$('modal-content').querySelector('h2');if(heading){heading.id='modal-title';$('modal').setAttribute('aria-labelledby','modal-title');}if(!$('modal').open)$('modal').showModal();}
function closeModal(){modalGeneration++;cancelAnimationFrame(trainingFrame);trainingSession=null;$('modal').close();}
$('close-modal').addEventListener('click',closeModal);$('modal').addEventListener('cancel',()=>{modalGeneration++;cancelAnimationFrame(trainingFrame);trainingSession=null;});$('modal').addEventListener('click',e=>{if(e.target!==$('modal'))return;const r=$('modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();});
function help(){openModal(`<div class="eyebrow">YENİ DÜELLO KURALLARI</div><h2>Bugünü vur. Yarını düşün.</h2><p>Kendi kalene dokun, kahramanınla bir hamle seç, sonra hedefini savaş alanında göster. Saldırı ve savunma sırasında sahadan ayrılmazsın.</p><div class="help-steps"><div class="help-step"><span>1</span><div><strong>Tek enerji, iki karar.</strong><p>İlk hamleyi yapan 3/6, yanıtlayan 4/6 enerjiyle başlar. Bu açık fark ilk hamle avantajını azaltır. İlk düelloda kura, sonraki düellolarda değişen sıra kullanılır. İlk saldırıdan sonra kendi saldırı sıranın başında +3 yenilenir. Saldırıyla savunma arasında sana enerji gelmez. Ağır darbe için harcadığın 4 enerji, yaklaşan 2 enerjilik siperi imkânsız kılabilir.</p></div></div><div class="help-step"><span>2</span><div><strong>Kahramanını da harcarsın.</strong><p>Saldıran muhafız hemen sonraki savunmada dinlenir. Savunan muhafız hemen sonraki saldırında dinlenir. Diğer muhafızlar her dost kaleyi koruyabilir. Kendi kalesini koruyan muhafız +8 yerel siper kazanır.</p></div></div><div class="help-step"><span>3</span><div><strong>Hazırla, sez, boz.</strong><p>Hazırlan: bu saldırından vazgeç, +2 enerji ve kahramana bir kullanımlık +18 güç al. Güç saldırıya ya da eşleşen sipere gider; birikmez. Bozucu darbe hasar geçirirse hedef kaledeki hazırlığı siler ve rakibin 1 enerjisini eksiltir.</p></div></div></div><p class="modal-note">Kora taş, İlda ok, Neris ses savunur. Yanlış tür: 0 koruma, enerji ve yorgunluk yine harcanır. Ücretsiz Siper her türe 12 korur; ücretsiz Temel Atış 18 vurur. Kilitlenmezsin. Bir yan kuleyi yıkarak ana kaleyi aç, ana kaleyi yıkarak kazan.</p><button class="primary-button" data-modal-action="close">Meydana dön ${icon('chevron')}</button>`);}
$('help-button').addEventListener('click',help);
function settingsModal(){openModal(`<div class="eyebrow">KENDİ TEMPOUNDA OYNA</div><h2>Düello ayarları</h2><div class="settings-row"><div><strong>Kora’nın eğitim gelişimi</strong><small>En iyi talim: +${settings.bestTraining} kalıcı saldırı. Yeni düelloda uygulanır; en fazla +3.<br>Karşılaştırmak için kapatıp yeni düello başlat.</small></div><input id="bonus-toggle" class="toggle" type="checkbox" ${settings.trainingEnabled?'checked':''} aria-label="Eğitim bonusunu yeni düelloda uygula"></div><div class="settings-row"><div><strong>Ses efektleri</strong><small>Bu cihazda saklanır.</small></div><input id="sound-toggle" class="toggle" type="checkbox" ${settings.sound?'checked':''} aria-label="Ses efektlerini aç"></div><div class="settings-row"><div><strong>Bu düellodaki Kora</strong><small>Hızlı: ${50+state.training.power} · Ağır: ${76+state.training.power} · Boz: ${34+state.training.power}. Hazırlık bunlara ayrıca +18 ekleyebilir.</small></div></div><div class="settings-actions"><button class="primary-button" data-modal-action="new">${icon('refresh')} Bu ayarlarla yeni düello</button><button class="secondary-button" data-modal-action="stories">Muhafızların hikâyesi</button><button class="secondary-button danger-button" data-modal-action="reset-confirm">Bu cihazdaki ilerlemeyi temizle</button></div><p style="margin-top:17px;font-size:10px">Hesap ve ödeme yok. Düello ve talim bu tarayıcıda tutulur.${storageAvailable?'':' Kayıt alanı kullanılamıyor; sekme kapanırsa ilerleme kaybolabilir.'}</p>`);$('bonus-toggle').addEventListener('change',e=>{settings.trainingEnabled=e.target.checked;persist();});$('sound-toggle').addEventListener('change',e=>{settings.sound=e.target.checked;soundIcon();persist();if(settings.sound)sound('select');});}
$('settings-button').addEventListener('click',settingsModal);
function resetConfirm(){openModal(`<div class="eyebrow">YENİ BİR SAYFA</div><h2>İlerleme temizlensin mi?</h2><p>Bu oyunun düellosu, eğitim derecesi ve ses ayarı bu tarayıcıdan silinir. Geri alınamaz. Başka sitelerin verilerine dokunulmaz.</p><button class="primary-button" data-modal-action="reset">Evet, ilerlemeyi temizle</button><button class="secondary-button" data-modal-action="settings" style="width:100%;margin-top:12px">Vazgeç</button>`);}
function stories(){openModal(`<div class="eyebrow">ÜÇ MUHAFIZ. TEK SANCAK.</div><h2>Onları tanı.</h2><div class="story-heroes"><div class="story-hero">${portrait('kora')}<div><h3>Kora <small>TAŞ MUHAFIZI</small></h3><p>Dağ köyünün son taş ustası. Yıktığı her duvar için bir köprü kuracağına söz verdi. Sabırlı, inatçı, beklenmedik kadar nazik.</p><em>“Sağlam dur. Gerisini ben hallederim.”</em></div></div><div class="story-hero">${portrait('ilda')}<div><h3>İlda <small>OK USTASI</small></h3><p>Ormanın kayıp patikalarını ezbere bilir. Bir zamanlar habercilik yapardı; şimdi okları rüzgârdan önce varır.</p><em>“Rüzgâr bir şey söylüyor. Ben duydum.”</em></div></div><div class="story-hero">${portrait('neris')}<div><h3>Neris <small>YANKI KORUYUCUSU</small></h3><p>Sessiz Göl’ün çanlarını yeniden çaldıran gezgin. Sesiyle taşı titreştirir, sessizliğiyle saldırıyı durdurur.</p><em>“En güçlü ses, doğru anda duyulandır.”</em></div></div></div><button class="primary-button" data-modal-action="close">Meydana dön</button>`);}
$('stories-button').addEventListener('click',stories);
$('log-button').addEventListener('click',()=>openModal(`<div class="eyebrow">SON HAMLELER</div><h2>Savaş günlüğü</h2><ol class="log-list">${[...state.log].reverse().map(t=>`<li>${esc(t)}</li>`).join('')}</ol><button class="primary-button" data-modal-action="close">Düelloya dön</button>`));
$('enemy-info-button').addEventListener('click',()=>openModal(`<div class="eyebrow">KIZIL SANCAK · AÇIK BİLGİ</div><h2>Rakibin neye hazır?</h2><p>Rakip ${state.energy.enemy}/6 enerjiye sahip. Saldırısı ve savunması aynı kaynağı harcar. Sana görünmeyen güç veya bilgi kullanmaz.</p><div class="story-heroes">${ids.map(id=>{const h=state.heroes.enemy[id];return `<div class="story-hero">${portrait(id)}<div><h3>${HEROES[id].name}</h3><p>${castleNames[h.castleId]} · ${h.retreatRounds?'Çekiliyor':isReady('enemy',id)?'Hazır':'Sonraki kararında dinleniyor'}<br>Hazırlık: ${h.charge?'+'+h.charge:'yok'}<br>Hızlı ${HEROES[id].attack} · Ağır ${HEROES[id].attack+26}<br>Eşleşen siper ${HEROES[id].guard} · Kendi kalesinde +8</p></div></div>`;}).join('')}</div><button class="primary-button" data-modal-action="close">Düelloya dön</button>`));
function showFinish(){if(state.phase!=='finished')return;const won=state.winner==='player';openModal(`<div class="win-content"><div class="modal-crest">${icon(won?'flag':'shield')}</div><div class="eyebrow" style="justify-content:center">${won?'SANCAGIN YÜKSELİYOR':'BİR SONRAKİ PLANIN'}</div><h2>${won?'Krallık güvende.':'Bu son hamlen değil.'}</h2><p>${won?'Rakibin ana kalesi düştü. Enerjini ve muhafızlarını birlikte yönettin.':'Ana kalen düştü. Bir sonraki düelloda ağır saldırıdan sonra savunmaya ne kaldığını düşün.'}</p><div class="win-stats"><div><strong>${state.round}</strong><small>TUR</small></div><div><strong>${state.castles.player.filter(c=>c.hp>0).length}</strong><small>AYAKTA KALE</small></div><div><strong>+${state.training.power}</strong><small>KORA GELİŞİMİ</small></div></div><button class="primary-button" data-modal-action="new">${icon('refresh')} Sıra değişsin · Rövanş</button><button class="secondary-button" data-modal-action="close">Savaş alanına bak</button></div>`);}
function training(){openModal(`<div class="training-header">${portrait('kora')}<div><div class="eyebrow">KORA’NIN TALİM ALANI</div><h2>Gücünü zamanla.</h2><p>İşaretçi altın bölgenin ortasındayken vur. Üç atış, bir gelişim derecesi.</p></div></div><div class="training-range"><span class="training-zone"></span><span id="training-marker" class="training-marker"></span></div><p class="training-instructions">Tam ortaya yaklaştıkça daha iyi derece kazanırsın.</p><div class="training-shots" id="training-shots"><span class="training-shot">1</span><span class="training-shot">2</span><span class="training-shot">3</span></div><button class="primary-button" id="training-hit">${icon('stone')} Şimdi vur!</button><div id="training-feedback" role="status" aria-live="polite" style="text-align:center;min-height:25px;margin-top:13px;font-size:12px;color:var(--gold)">Hazır olduğunda ilk atışını yap.</div><p class="modal-note" style="margin-top:17px">En iyi derecen kalıcıdır. Kora’nın özel saldırıları en fazla +3 gelişir; hızlı vuruş 50 → 53. Hazırlık ve enerji yine aynı kurallarla çalışır. Yeni düelloda uygulanır, ayarlardan kapatılabilir.</p>`);trainingSession={start:performance.now(),position:.5,scores:[],lock:false};const tick=now=>{if(!trainingSession||!$('modal').open)return;trainingSession.position=.5+Math.sin((now-trainingSession.start)/(580-trainingSession.scores.length*70))*.47;const marker=$('training-marker');if(marker)marker.style.left=trainingSession.position*100+'%';trainingFrame=requestAnimationFrame(tick);};trainingFrame=requestAnimationFrame(tick);$('training-hit').addEventListener('click',trainingHit);}
function trainingHit(){const session=trainingSession;if(!session||session.lock)return;session.lock=true;const distance=Math.abs(session.position-.5),score=distance<=.08?100:distance<=.2?65:25;session.scores.push(score);sound(score===100?'guard':'hit');$('training-shots').innerHTML=[0,1,2].map(i=>`<span class="training-shot ${i<session.scores.length?'done':''}">${session.scores[i]===100?'✦':session.scores[i]===65?'✓':session.scores[i]===25?'·':i+1}</span>`).join('');$('training-feedback').textContent=score===100?'Tam isabet!':score===65?'İyi atış. Merkeze biraz daha yaklaş.':'Kaya hedefi sıyırdı. Yeniden odaklan.';if(session.scores.length===3){cancelAnimationFrame(trainingFrame);const avg=session.scores.reduce((a,b)=>a+b,0)/3,tier=avg>=90?3:avg>=65?2:avg>=35?1:0;settings.bestTraining=Math.max(settings.bestTraining,tier);persist();trainingSession=null;$('training-hit').disabled=true;const expectedModal=modalGeneration;setTimeout(()=>{if(modalGeneration!==expectedModal||!$('modal').open||!$('training-hit'))return;openModal(`<div class="eyebrow">TALİM TAMAMLANDI</div><h2>${tier===3?'Taş gibi isabet.':tier===2?'Bileğin güçleniyor.':tier===1?'İlk adım atıldı.':'Bir daha deneyelim.'}</h2><div class="training-result"><div class="star-row">${'★'.repeat(tier)}${'☆'.repeat(3-tier)}</div><strong>+${tier} saldırı gelişimi</strong><p>En iyi kaydın +${settings.bestTraining}<br>Kora hızlı ${50+settings.bestTraining} · ağır ${76+settings.bestTraining} · bozucu ${34+settings.bestTraining}</p></div><p class="modal-note">Kalıcı gelişim küçük ve sınırlıdır. Enerji, yorgunluk ve karşı hamle kararları hâlâ belirleyici. Yeni düello mevcut savaşı sıfırlar.</p><button class="primary-button" data-modal-action="training-new">Gelişmiş Kora ile yeni düello</button><button class="secondary-button" data-modal-action="training" style="width:100%;margin-top:12px">Yeniden talim yap</button><button class="text-button" data-modal-action="close" style="width:100%;text-align:center">Mevcut düelloya dön</button>`);},800);}else setTimeout(()=>{if(trainingSession===session)session.lock=false;},350);}
$('training-button').addEventListener('click',training);
$('modal-content').addEventListener('click',e=>{const a=e.target.closest('[data-modal-action]')?.dataset.modalAction;if(!a)return;if(a==='close')closeModal();else if(a==='new')newGame();else if(a==='settings')settingsModal();else if(a==='stories')stories();else if(a==='reset-confirm')resetConfirm();else if(a==='reset'){settings={sound:false,trainingEnabled:true,bestTraining:0};try{localStorage.removeItem(STORE);localStorage.removeItem('kale-muhafizlari-v1');}catch{}soundIcon();newGame();toast('İlerleme temizlendi. Yeni düello hazır.');}else if(a==='training')training();else if(a==='training-new'){settings.trainingEnabled=true;newGame();}});
window.addEventListener('pagehide',persist);
render();if(['aiAttack','aiDefense'].includes(state.phase))drive();else if(state.phase==='finished')finishShown=true;
if(oldSaved&&!saved)toast('Yeni düello kuralları hazır. Talim derecen korundu; savaş yeniden başlıyor.');
if(!storageAvailable)toast('Bu tarayıcı ilerlemeyi kaydedemiyor. Oyun açık sekmede devam eder.');
